#include <iostream>
using namespace std;

int main() {
    int n, besar = 0, total = 0;
    cout << "Berapa angka? ";
    cin >> n;
    for (int i = 1; i <= n; i++) {
        int x;
        cin >> x;
        total += x;
        if (x > 5) besar++;
    }
    cout << "Total = " << total << endl;
    cout << "Rata-rata = " << (float)total / n << endl;
    cout << "Lebih dari 5 = " << besar;
    return 0;
}
